public class ServersTest {

  private Servers servers;

  @BeforeEach
  void setUp() throws Exception {
    DataSource raw = new JDBCDataSource();
    ((JDBCDataSource) raw).setUrl("jdbc:hsqldb:mem:servers_test");
    ((JDBCDataSource) raw).setUser("SA");
    ((JDBCDataSource) raw).setPassword("");

    try (Connection c = raw.getConnection();
        Statement s = c.createStatement()) {
      s.execute(
          "CREATE TABLE SERVERS (id VARCHAR(50), hostname VARCHAR(50), ip VARCHAR(50),"
              + " mac VARCHAR(50), status VARCHAR(50), description VARCHAR(50))");
      s.execute("INSERT INTO SERVERS VALUES ('1','server1','10.0.0.1','AA','active','desc1')");
      s.execute("INSERT INTO SERVERS VALUES ('2','server2','10.0.0.2','BB','active','desc2')");
      s.execute("CREATE TABLE user_system_data (username VARCHAR(50), password VARCHAR(50))");
      s.execute("INSERT INTO user_system_data VALUES ('admin','secret')");
    }

    servers = new Servers(new LessonDataSource(raw));
  }

  @Test
  void rejectsSqlInjectionViaColumnParameter() {
    // The `column` request parameter is concatenated directly into the ORDER BY
    // clause of the SQL query. A safe implementation must reject anything that
    // is not a plain column name. This value is valid SQL that reads from a
    // table the application never queries, proving the tainted input is
    // executed as SQL instead of being treated as a literal column name.
    assertThrows(
        Exception.class,
        () ->
            servers.sort(
                "CASE WHEN (SELECT COUNT(*) FROM user_system_data) > 0 THEN hostname ELSE ip END"));
  }
}
